package com.example.agendapersonal.avisos;

import android.app.*;import android.content.*;import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;import android.os.*;import android.net.Uri;import android.provider.Settings;
import com.example.agendapersonal.data.DatabaseHelper;import com.example.agendapersonal.ui.registro.Registro;import com.example.agendapersonal.eventos.SeriesEvento;import com.example.agendapersonal.ui.*;
import java.time.*;import java.util.*;import java.util.concurrent.*;

/** Recalcula desde los datos locales. Los permisos los concede el usuario desde Ajustes. */
public final class ProgramadorAvisos {
 private static final ScheduledExecutorService COLA=Executors.newSingleThreadScheduledExecutor();private static ScheduledFuture<?> pendiente;
 public static final String RECORDATORIOS="agenda_recordatorios",CRITICOS="agenda_criticos",FLOTANTE="agenda_flotante";
 private ProgramadorAvisos(){}
 public static synchronized void actualizar(Context c){Context app=c.getApplicationContext();if(pendiente!=null)pendiente.cancel(false);pendiente=COLA.schedule(()->{try{recalcular(app);}catch(RuntimeException e){android.util.Log.e("AgendaPersonal","Programar avisos",e);}},700,TimeUnit.MILLISECONDS);}
 public static void ejecutar(Context c,Runnable finalizado){COLA.execute(()->{try{recalcular(c.getApplicationContext());}catch(RuntimeException e){android.util.Log.e("AgendaPersonal","Recibir avisos",e);}finally{finalizado.run();}});}
 public static void canales(Context c){NotificationManager n=c.getSystemService(NotificationManager.class);n.createNotificationChannel(new NotificationChannel(RECORDATORIOS,"Recordatorios de tareas y eventos",NotificationManager.IMPORTANCE_HIGH));n.createNotificationChannel(new NotificationChannel(CRITICOS,"Actividades críticas de hoy",NotificationManager.IMPORTANCE_HIGH));n.createNotificationChannel(new NotificationChannel(FLOTANTE,"Ventana de actividades de hoy",NotificationManager.IMPORTANCE_LOW));}
 public static boolean permiso(Context c){return (Build.VERSION.SDK_INT<33||c.checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)==android.content.pm.PackageManager.PERMISSION_GRANTED)&&c.getSystemService(NotificationManager.class).areNotificationsEnabled();}
 private static boolean activo(Registro r){return !Arrays.asList("FINALIZADO","CANCELADO","POSTERGADO").contains(r.texto("estadoEspecial"));}
 public static final class Aviso {public final String tabla;public final Registro registro;public final long alarma;Aviso(String t,Registro r){tabla=t;registro=r;long a=Long.MAX_VALUE;if(activo(r)&&Boolean.parseBoolean(r.texto("alarmaActivada"))){String fecha=r.texto(t.equals("tareas")?"fechaInicio":"fecha"),hora=r.texto(t.equals("tareas")?"horaInicio":"hora");if(!fecha.isEmpty())try{a=HoraAviso.calcular(fecha,hora,Long.parseLong(r.texto("anticipacionMinutos").isEmpty()?"0":r.texto("anticipacionMinutos")),ZoneId.systemDefault());}catch(RuntimeException ignored){}}alarma=a;}
  public String clave(){return tabla+":"+registro.texto("id");}public Intent abrir(Context c){Intent i=new Intent(c,tabla.equals("tareas")?TareasActivity.class:EventosActivity.class).putExtra("registroId",registro.texto("id")).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP);if(!registro.texto("_serie").isEmpty())i.putExtra("serieId",registro.texto("_serie")).putExtra("ordinal",Long.parseLong(registro.texto("_ordinal")));return i;}}
 private static Registro leer(Cursor c){Registro r=new Registro();for(String k:c.getColumnNames()){StringBuilder camel=new StringBuilder();boolean may=false;for(char x:k.toCharArray()){if(x=='_')may=true;else{camel.append(may?Character.toUpperCase(x):x);may=false;}}int ix=c.getColumnIndexOrThrow(k);r.put(camel.toString(),c.isNull(ix)?null:c.getString(ix));}r.put("alarmaActivada",String.valueOf(c.getInt(c.getColumnIndexOrThrow("alarma_activada"))!=0));return r;}
 public static List<Aviso> todos(Context c){List<Aviso> lista=new ArrayList<>();Set<Long> anticipaciones=new HashSet<>();anticipaciones.add(0L);try(DatabaseHelper h=new DatabaseHelper(c)){SQLiteDatabase db=h.getReadableDatabase();for(String tabla:new String[]{"tareas","eventos"})try(Cursor q=db.query(tabla,null,"deleted_at IS NULL",null,null,null,null)){while(q.moveToNext()){Registro r=leer(q);lista.add(new Aviso(tabla,r));}}try(Cursor q=db.rawQuery("SELECT configuracion_personalizada FROM series_eventos WHERE deleted_at IS NULL",null)){while(q.moveToNext())try{org.json.JSONArray segmentos=new org.json.JSONObject(q.getString(0)).getJSONArray("segmentos");for(int j=0;j<segmentos.length();j++)anticipaciones.add(Math.max(0,segmentos.getJSONObject(j).getJSONObject("plantilla").optLong("anticipacionMinutos",0)));}catch(org.json.JSONException|NullPointerException ignored){}}}
  // Se calcula hasta más allá de la mayor anticipación. El despertar diario extiende el horizonte.
  LocalDate hoy=LocalDate.now();Set<String> ids=new HashSet<>();for(long anticipacion:anticipaciones){LocalDate centro=hoy.plusDays(anticipacion/1440);for(Registro r:SeriesEvento.virtuales(c,centro.minusDays(1),centro.plusDays(3)))if(ids.add(r.texto("id")))lista.add(new Aviso("eventos",r));}return lista;}
 public static List<Aviso> criticos(Context c){List<Aviso> r=new ArrayList<>();String hoy=LocalDate.now().toString();for(Aviso a:todos(c))if(activo(a.registro)&&hoy.equals(a.registro.texto(a.tabla.equals("tareas")?"fechaVencimiento":"fecha")))r.add(a);return r;}
 private static PendingIntent alarma(Context c){return PendingIntent.getBroadcast(c,72,new Intent(c,ReceptorAvisos.class).setAction("com.example.agendapersonal.AVISOS"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 private static String firma(Aviso a){return a.alarma+"|"+a.registro.texto("revision");}
 private static void recalcular(Context c){canales(c);long ahora=System.currentTimeMillis();SharedPreferences p=c.getSharedPreferences("agenda_avisos",Context.MODE_PRIVATE);long desde=p.getLong("ultima_revision",ahora);boolean habilitado=permiso(c);List<Aviso> datos=todos(c),hoy=new ArrayList<>();Set<String>vigentes=new HashSet<>();long proxima=LocalDate.now().plusDays(1).atStartOfDay(ZoneId.systemDefault()).toInstant().toEpochMilli();String dia=LocalDate.now().toString();
  for(Aviso a:datos){if(!activo(a.registro))continue;boolean critico=dia.equals(a.registro.texto(a.tabla.equals("tareas")?"fechaVencimiento":"fecha"));if(critico){hoy.add(a);String tag="critico:"+a.clave();vigentes.add(tag);if(habilitado&&!dia.equals(p.getString(tag,""))){mostrar(c,a,CRITICOS,tag,"Para hoy");p.edit().putString(tag,dia).apply();}}
   if(a.alarma==Long.MAX_VALUE)continue;String tag="recordatorio:"+a.clave();vigentes.add(tag);if(a.alarma>ahora){proxima=Math.min(proxima,a.alarma);if(!firma(a).equals(p.getString(tag,"")))c.getSystemService(NotificationManager.class).cancel(tag,1);}else if(a.alarma>=desde&&habilitado&&!firma(a).equals(p.getString(tag,""))){mostrar(c,a,RECORDATORIOS,tag,"Recordatorio");p.edit().putString(tag,firma(a)).apply();}}
  NotificationManager nm=c.getSystemService(NotificationManager.class);for(StatusBarNotificationWrapper n:activas(nm))if(n.tag!=null&&(n.tag.startsWith("critico:")||n.tag.startsWith("recordatorio:"))&&!vigentes.contains(n.tag))nm.cancel(n.tag,n.id);
  if(habilitado)p.edit().putLong("ultima_revision",ahora).apply();AlarmManager am=c.getSystemService(AlarmManager.class);PendingIntent pi=alarma(c);if(Build.VERSION.SDK_INT<31||am.canScheduleExactAlarms())am.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,proxima,pi);else am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,proxima,pi);
  boolean flotante=p.getBoolean("flotante",false)&&Settings.canDrawOverlays(c)&&!hoy.isEmpty()&&habilitado;if(flotante)try{c.startForegroundService(new Intent(c,VentanaAvisos.class));}catch(IllegalStateException|SecurityException e){android.util.Log.i("AgendaPersonal","La ventana se abrirá al volver a la app");}else c.stopService(new Intent(c,VentanaAvisos.class));
 }
 private static final class StatusBarNotificationWrapper {String tag;int id;StatusBarNotificationWrapper(String t,int i){tag=t;id=i;}}
 private static List<StatusBarNotificationWrapper> activas(NotificationManager n){List<StatusBarNotificationWrapper>r=new ArrayList<>();for(android.service.notification.StatusBarNotification a:n.getActiveNotifications())r.add(new StatusBarNotificationWrapper(a.getTag(),a.getId()));return r;}
 private static void mostrar(Context c,Aviso a,String canal,String tag,String encabezado){Intent i=a.abrir(c).setData(Uri.parse("agenda://aviso/"+a.tabla+"/"+a.registro.texto("id")));PendingIntent pi=PendingIntent.getActivity(c,0,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);String texto=a.registro.texto("descripcion");Notification n=new Notification.Builder(c,canal).setSmallIcon(com.example.agendapersonal.R.drawable.ic_aviso_agenda).setContentTitle(encabezado+" · Agenda Personal").setContentText(texto).setStyle(new Notification.BigTextStyle().bigText(texto)).setContentIntent(pi).setAutoCancel(true).setCategory(Notification.CATEGORY_REMINDER).build();c.getSystemService(NotificationManager.class).notify(tag,1,n);}
}
